package com.arqly.backend.service;
import com.arqly.backend.dto.NotificationDtos.*;import com.arqly.backend.entity.*;import com.arqly.backend.exception.NotFoundException;import com.arqly.backend.repository.*;import java.time.Instant;import java.util.*;import org.springframework.data.domain.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class NotificationService {private final NotificationRepository notifications;private final NotificationPreferenceRepository preferences;private final TenantUserRepository users;public NotificationService(NotificationRepository notifications,NotificationPreferenceRepository preferences,TenantUserRepository users){this.notifications=notifications;this.preferences=preferences;this.users=users;}@Transactional(readOnly=true)public Page<NotificationResponse> list(UUID tenant,UUID user,NotificationStatus status,NotificationCategory category,NotificationPriority priority,Pageable pageable){return notifications.list(tenant,user,status,category,priority,pageable).map(this::response);}@Transactional(readOnly=true)public long unreadCount(UUID tenant,UUID user){return notifications.countByTenantIdAndRecipientUserIdAndStatus(tenant,user,NotificationStatus.UNREAD);}@Transactional public NotificationResponse read(UUID tenant,UUID user,UUID id,boolean read){var n=find(tenant,user,id);n.setStatus(read?NotificationStatus.READ:NotificationStatus.UNREAD);n.setReadAt(read?Instant.now():null);return response(n);}@Transactional public void archive(UUID tenant,UUID user,UUID id){var n=find(tenant,user,id);n.setStatus(NotificationStatus.ARCHIVED);n.setArchivedAt(Instant.now());}@Transactional public void readAll(UUID tenant,UUID user){notifications.list(tenant,user,NotificationStatus.UNREAD,null,null,Pageable.unpaged()).forEach(n->{n.setStatus(NotificationStatus.READ);n.setReadAt(Instant.now());});}@Transactional(readOnly=true)public List<NotificationPreferenceResponse> preferences(UUID tenant,UUID user){ensure(tenant,user);return Arrays.stream(NotificationCategory.values()).map(c->{var p=preferences.findByUserIdAndCategory(user,c).orElse(null);return new NotificationPreferenceResponse(c,p==null||p.isInAppEnabled(),p!=null&&p.isEmailEnabled());}).toList();}@Transactional public List<NotificationPreferenceResponse> updatePreferences(UUID tenant,UUID user,List<NotificationPreferenceRequest> requests){var u=ensure(tenant,user);for(var r:requests){var p=preferences.findByUserIdAndCategory(user,r.category()).orElseGet(()->{var value=new NotificationPreference();value.setUser(u);value.setCategory(r.category());return value;});p.setInAppEnabled(r.inAppEnabled());p.setEmailEnabled(r.emailEnabled());preferences.save(p);}return preferences(tenant,user);}
private Notification find(UUID tenant,UUID user,UUID id){return notifications.findByIdAndTenantIdAndRecipientUserId(id,tenant,user).orElseThrow(()->new NotFoundException("Notificação não encontrada."));}private TenantUser ensure(UUID tenant,UUID user){return users.findByIdAndTenantId(user,tenant).orElseThrow(()->new NotFoundException("Usuário não encontrado."));}private NotificationResponse response(Notification n){return new NotificationResponse(n.getId(),n.getType(),n.getCategory(),n.getTitle(),n.getMessage(),n.getPriority(),n.getStatus(),n.getSourceType(),n.getSourceId(),n.getActionUrl(),n.isMandatory(),n.getCreatedAt(),n.getReadAt());}}
